class DataCompressor{constructor(){this.isCompressionSupported="undefined"!=typeof pako,this.compressionLevel=6}async compressData(r){try{if(!this.isCompressionSupported)return console.warn("Compression not supported, returning original data"),JSON.stringify(r);const e="string"==typeof r?r:JSON.stringify(r),t=pako.gzip(e,{level:this.compressionLevel}),s=this.arrayBufferToBase64(t),o=new Blob([e]).size,a=new Blob([s]).size;return((o-a)/o*100).toFixed(1),this.formatBytes(o),this.formatBytes(a),s}catch(e){return console.error("Compression failed:",e),JSON.stringify(r)}}async decompressData(r){try{if(!this.isCompressionSupported)return JSON.parse(r);const e=this.base64ToArrayBuffer(r),t=pako.ungzip(e,{to:"string"});return JSON.parse(t)}catch(e){return console.error("Decompression failed:",e),JSON.parse(r)}}optimizeStructure(r){const e={id:r.surah_id,v:{}};for(const[t,s]of Object.entries(r.verses))if(e.v[t]={ar:s.arabic_text,bn:s.bangla_trans,en:s.english_trans},s.word_by_word){e.v[t].w={};for(const[r,o]of Object.entries(s.word_by_word))e.v[t].w[r]={ar:o.words_ar,bn:o.translate_bn}}return e}restoreStructure(r){const e={surah_id:r.id,verses:{}};for(const[t,s]of Object.entries(r.v))if(e.verses[t]={arabic_text:s.ar,bangla_trans:s.bn,english_trans:s.en},s.w){e.verses[t].word_by_word={};for(const[r,o]of Object.entries(s.w))e.verses[t].word_by_word[r]={words_ar:o.ar,translate_bn:o.bn}}return e}async storeCompressedData(r,e){try{const t=this.optimizeStructure(e),s={compressed:!0,data:await this.compressData(t),timestamp:Date.now()};localStorage.setItem(r,JSON.stringify(s))}catch(t){console.error("Failed to store compressed data:",t),localStorage.setItem(r,JSON.stringify({compressed:!1,data:e,timestamp:Date.now()}))}}async retrieveCompressedData(r){try{const e=localStorage.getItem(r);if(!e)return null;const t=JSON.parse(e);if(t.compressed){const r=await this.decompressData(t.data);return this.restoreStructure(r)}return t.data}catch(r){return console.error("Failed to retrieve compressed data:",r),null}}arrayBufferToBase64(r){let e="";const t=new Uint8Array(r);for(let r=0;r<t.byteLength;r++)e+=String.fromCharCode(t[r]);return btoa(e)}base64ToArrayBuffer(r){const e=atob(r),t=new Uint8Array(e.length);for(let r=0;r<e.length;r++)t[r]=e.charCodeAt(r);return t}formatBytes(r,e=2){if(0===r)return"0 Bytes";const t=e<0?0:e,s=Math.floor(Math.log(r)/Math.log(1024));return parseFloat((r/Math.pow(1024,s)).toFixed(t))+" "+["Bytes","KB","MB","GB"][s]}async testCompression(r){const e=await this.compressData(r),t=await this.decompressData(e);return JSON.stringify(r),JSON.stringify(t),{originalSize:JSON.stringify(r).length,compressedSize:e.length,integrityCheck:JSON.stringify(r)===JSON.stringify(t)}}}"undefined"!=typeof module&&module.exports?module.exports=DataCompressor:window.DataCompressor=DataCompressor;